@extends('layouts.storefront')
@section('title','Wishlist | MEETA')
@push('styles')<style>.page{padding-top:55px}.page h1{font-size:42px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:30px}.card{border:1px solid var(--line);background:#fff;padding:9px}.card img{width:100%;height:260px;object-fit:cover}.card h3{margin:14px 4px}.price{color:var(--brown);margin:0 4px 14px}.actions{display:grid;gap:8px}.empty{text-align:center;padding:100px}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:550px){.grid{grid-template-columns:1fr}}</style>@endpush
@section('content')<main class="page wrap"><h1>Your Wishlist</h1><p>Pieces worth remembering.</p><div id="list"><div class="loading">Opening your wishlist…</div></div></main>@endsection
@push('scripts')<script>if(!token)requireAuth();async function load(){try{const {data}=await api('/api/customer/wishlist');document.getElementById('list').innerHTML=data.items.length?`<div class="grid">${data.items.map(i=>`<article class="card"><a href="/products/${i.product.slug}"><img src="${i.product.image}" alt="${i.product.name}"><h3>${i.product.name}</h3></a><div class="price">₹${Number(i.product.effective_price).toLocaleString('en-IN')}</div><div class="actions"><button class="btn primary" data-move="${i.id}">Move to Cart</button><button class="btn" data-remove="${i.id}">Remove</button></div></article>`).join('')}</div>`:'<div class="empty"><h2>No saved pieces yet.</h2><a class="btn primary" href="/categories">Explore Crafts</a></div>';document.querySelectorAll('[data-move]').forEach(b=>b.onclick=async()=>{try{await api('/api/customer/wishlist/items/'+b.dataset.move+'/move-to-cart',{method:'POST'});toast('Moved to cart');load()}catch(e){toast(e.message)}});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{await api('/api/customer/wishlist/items/'+b.dataset.remove,{method:'DELETE'});load()})}catch(e){toast(e.message)}}load();</script>@endpush
